      { label: 'AllMusic profile', href: 'https://www.allmusic.com/search/all/Fat%20Joe', note: 'Useful for discography orientation and style framing.' },
      { label: 'Billboard coverage', href: 'https://www.billboard.com/search/Fat%20Joe/', note: 'Best source for chart milestones, release cycles, and crossover-era reporting.' },
      { label: 'Rolling Stone features', href: 'https://www.rollingstone.com/search/Fat%20Joe/', note: 'Useful for profiles, interviews, and broader New York scene framing.' },
      { label: 'Discogs search', href: 'https://www.discogs.com/search/?q=Fat%20Joe&type=all', note: 'Helpful for checking releases and credits.' }
